-- =====================================================================
-- Bus Booking & Cancellation System  |  MySQL 8.0+ (InnoDB, utf8mb4)
-- Single-company operator | 24 tables
-- Run the whole script top to bottom: tables are in FK-safe order.
-- Note: CHECK constraints are enforced from MySQL 8.0.16 onward.
-- PostgreSQL -> MySQL mapping used:
--   SERIAL   -> INT AUTO_INCREMENT
--   INTERVAL -> TIME  (estimated_duration, arrival_offset)
--   TEXT / TIMESTAMP kept; updated_at uses ON UPDATE CURRENT_TIMESTAMP
-- =====================================================================

CREATE DATABASE IF NOT EXISTS bus_booking_db
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE bus_booking_db;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS
  Operators, Admin_users, Reviews_ratings, Notifications, Booking_coupons,
  Coupons, Refunds, Cancellations, Payments, Booking_passengers, Bookings,
  Passengers, Users, Trip_seats, Trips, Drivers, Route_stops, Routes,
  Bus_amenities, Seat_layout, Buses, Bus_types, Terminals, Cities;
SET FOREIGN_KEY_CHECKS = 1;

-- =====================================================================
-- STEP 1: LOCATION & ROUTE FOUNDATION
-- =====================================================================

-- 1. Cities
CREATE TABLE Cities (
  city_id       INT AUTO_INCREMENT PRIMARY KEY,
  city_name     VARCHAR(100) NOT NULL,
  city_code     VARCHAR(10)  NOT NULL,
  state         VARCHAR(100) NOT NULL,
  country       VARCHAR(100) NOT NULL DEFAULT 'India',
  latitude      DECIMAL(9,6),
  longitude     DECIMAL(9,6),
  is_major_hub  BOOLEAN NOT NULL DEFAULT FALSE,
  status        VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT uq_cities_code UNIQUE (city_code),
  CONSTRAINT chk_cities_status CHECK (status IN ('active','inactive'))
) ENGINE=InnoDB;

-- 2. Terminals
CREATE TABLE Terminals (
  terminal_id    INT AUTO_INCREMENT PRIMARY KEY,
  city_id        INT NOT NULL,
  terminal_name  VARCHAR(150) NOT NULL,
  address        VARCHAR(255),
  latitude       DECIMAL(9,6),
  longitude      DECIMAL(9,6),
  status         VARCHAR(20) NOT NULL DEFAULT 'active',
  CONSTRAINT fk_terminals_city FOREIGN KEY (city_id) REFERENCES Cities(city_id),
  CONSTRAINT chk_terminals_status CHECK (status IN ('active','inactive')),
  INDEX idx_terminals_city (city_id)
) ENGINE=InnoDB;

-- =====================================================================
-- STEP 2: FLEET SETUP
-- =====================================================================

-- 3. Bus_types
CREATE TABLE Bus_types (
  bus_type_id  INT AUTO_INCREMENT PRIMARY KEY,
  type_name    VARCHAR(50) NOT NULL,
  category     VARCHAR(20) NOT NULL,
  ac_type      VARCHAR(10) NOT NULL,
  description  VARCHAR(255),
  status       VARCHAR(20) NOT NULL DEFAULT 'active',
  CONSTRAINT uq_bus_types_name UNIQUE (type_name),
  CONSTRAINT chk_bus_types_category CHECK (category IN ('Seater','Sleeper','Semi-Sleeper')),
  CONSTRAINT chk_bus_types_ac CHECK (ac_type IN ('AC','Non-AC')),
  CONSTRAINT chk_bus_types_status CHECK (status IN ('active','inactive'))
) ENGINE=InnoDB;

-- 4. Buses
CREATE TABLE Buses (
  bus_id               INT AUTO_INCREMENT PRIMARY KEY,
  bus_type_id          INT NOT NULL,
  registration_number  VARCHAR(20) NOT NULL,
  bus_name             VARCHAR(100),
  total_seats          INT NOT NULL,
  manufacture_year     INT,
  status               VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT uq_buses_reg UNIQUE (registration_number),
  CONSTRAINT fk_buses_type FOREIGN KEY (bus_type_id) REFERENCES Bus_types(bus_type_id),
  CONSTRAINT chk_buses_seats CHECK (total_seats > 0),
  CONSTRAINT chk_buses_status CHECK (status IN ('active','maintenance','retired')),
  INDEX idx_buses_type (bus_type_id)
) ENGINE=InnoDB;

-- 5. Seat_layout
CREATE TABLE Seat_layout (
  seat_id           INT AUTO_INCREMENT PRIMARY KEY,
  bus_id            INT NOT NULL,
  seat_number       VARCHAR(10) NOT NULL,
  row_no            INT,
  column_no         INT,
  deck              VARCHAR(10) NOT NULL DEFAULT 'lower',
  berth_type        VARCHAR(20) NOT NULL DEFAULT 'seater',
  seat_position     VARCHAR(10),
  is_ladies_seat    BOOLEAN NOT NULL DEFAULT FALSE,
  price_multiplier  DECIMAL(3,2) NOT NULL DEFAULT 1.00,
  status            VARCHAR(20) NOT NULL DEFAULT 'active',
  CONSTRAINT uq_seat_bus_number UNIQUE (bus_id, seat_number),
  CONSTRAINT fk_seat_bus FOREIGN KEY (bus_id) REFERENCES Buses(bus_id),
  CONSTRAINT chk_seat_deck CHECK (deck IN ('lower','upper')),
  CONSTRAINT chk_seat_berth CHECK (berth_type IN ('seater','sleeper')),
  CONSTRAINT chk_seat_position CHECK (seat_position IS NULL OR seat_position IN ('window','aisle')),
  CONSTRAINT chk_seat_status CHECK (status IN ('active','inactive'))
) ENGINE=InnoDB;

-- 6. Bus_amenities
CREATE TABLE Bus_amenities (
  amenity_id    INT AUTO_INCREMENT PRIMARY KEY,
  bus_id        INT NOT NULL,
  amenity_name  VARCHAR(50) NOT NULL,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_amenity_bus_name UNIQUE (bus_id, amenity_name),
  CONSTRAINT fk_amenity_bus FOREIGN KEY (bus_id) REFERENCES Buses(bus_id)
) ENGINE=InnoDB;

-- =====================================================================
-- STEP 3: ROUTE DEFINITION
-- =====================================================================

-- 7. Routes
CREATE TABLE Routes (
  route_id                 INT AUTO_INCREMENT PRIMARY KEY,
  route_code               VARCHAR(20) NOT NULL,
  route_name               VARCHAR(150) NOT NULL,
  source_city_id           INT NOT NULL,
  destination_city_id      INT NOT NULL,
  source_terminal_id       INT,
  destination_terminal_id  INT,
  distance_km              DECIMAL(6,2),
  estimated_duration       TIME,
  base_fare                DECIMAL(8,2) NOT NULL DEFAULT 0.00,
  route_type               VARCHAR(20) NOT NULL DEFAULT 'one-way',
  status                   VARCHAR(20) NOT NULL DEFAULT 'active',
  is_night_route           BOOLEAN NOT NULL DEFAULT FALSE,
  created_at               TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at               TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT uq_routes_code UNIQUE (route_code),
  CONSTRAINT fk_routes_src_city FOREIGN KEY (source_city_id) REFERENCES Cities(city_id),
  CONSTRAINT fk_routes_dst_city FOREIGN KEY (destination_city_id) REFERENCES Cities(city_id),
  CONSTRAINT fk_routes_src_term FOREIGN KEY (source_terminal_id) REFERENCES Terminals(terminal_id),
  CONSTRAINT fk_routes_dst_term FOREIGN KEY (destination_terminal_id) REFERENCES Terminals(terminal_id),
  CONSTRAINT chk_routes_cities CHECK (source_city_id <> destination_city_id),
  CONSTRAINT chk_routes_type CHECK (route_type IN ('one-way','round-trip')),
  CONSTRAINT chk_routes_status CHECK (status IN ('active','inactive','seasonal','suspended')),
  INDEX idx_routes_src_dst (source_city_id, destination_city_id)
) ENGINE=InnoDB;

-- 8. Route_stops
CREATE TABLE Route_stops (
  route_stop_id            INT AUTO_INCREMENT PRIMARY KEY,
  route_id                 INT NOT NULL,
  city_id                  INT NOT NULL,
  terminal_id              INT,
  stop_sequence            INT NOT NULL,
  stop_type                VARCHAR(20) NOT NULL DEFAULT 'both',
  distance_from_origin_km  DECIMAL(6,2) NOT NULL DEFAULT 0.00,
  arrival_offset           TIME,
  halt_duration_minutes    INT NOT NULL DEFAULT 0,
  is_major_stop            BOOLEAN NOT NULL DEFAULT TRUE,
  status                   VARCHAR(20) NOT NULL DEFAULT 'active',
  CONSTRAINT uq_route_stop_seq UNIQUE (route_id, stop_sequence),
  CONSTRAINT fk_rstops_route FOREIGN KEY (route_id) REFERENCES Routes(route_id),
  CONSTRAINT fk_rstops_city FOREIGN KEY (city_id) REFERENCES Cities(city_id),
  CONSTRAINT fk_rstops_terminal FOREIGN KEY (terminal_id) REFERENCES Terminals(terminal_id),
  CONSTRAINT chk_rstops_type CHECK (stop_type IN ('boarding','dropping','both')),
  CONSTRAINT chk_rstops_status CHECK (status IN ('active','inactive')),
  INDEX idx_rstops_city (city_id)
) ENGINE=InnoDB;

-- =====================================================================
-- STEP 4: SCHEDULING ENGINE
-- =====================================================================

-- 9. Drivers
CREATE TABLE Drivers (
  driver_id         INT AUTO_INCREMENT PRIMARY KEY,
  full_name         VARCHAR(150) NOT NULL,
  phone_number      VARCHAR(15) NOT NULL,
  license_number    VARCHAR(50) NOT NULL,
  license_expiry    DATE,
  experience_years  INT,
  status            VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT uq_drivers_phone UNIQUE (phone_number),
  CONSTRAINT uq_drivers_license UNIQUE (license_number),
  CONSTRAINT chk_drivers_status CHECK (status IN ('active','on_leave','inactive'))
) ENGINE=InnoDB;

-- 10. Trips (the bookable unit)
CREATE TABLE Trips (
  trip_id          INT AUTO_INCREMENT PRIMARY KEY,
  route_id         INT NOT NULL,
  bus_id           INT NOT NULL,
  driver_id        INT NULL,
  departure_date   DATE NOT NULL,
  departure_time   TIME NOT NULL,
  arrival_date     DATE NOT NULL,
  arrival_time     TIME NOT NULL,
  fare             DECIMAL(8,2) NOT NULL,
  available_seats  INT NOT NULL DEFAULT 0,
  status           VARCHAR(20) NOT NULL DEFAULT 'scheduled',
  created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_trips_route FOREIGN KEY (route_id) REFERENCES Routes(route_id),
  CONSTRAINT fk_trips_bus FOREIGN KEY (bus_id) REFERENCES Buses(bus_id),
  CONSTRAINT fk_trips_driver FOREIGN KEY (driver_id) REFERENCES Drivers(driver_id),
  CONSTRAINT chk_trips_fare CHECK (fare >= 0),
  CONSTRAINT chk_trips_avail CHECK (available_seats >= 0),
  CONSTRAINT chk_trips_status CHECK (status IN ('scheduled','departed','completed','cancelled')),
  -- a bus cannot depart twice at the same date/time
  CONSTRAINT uq_trips_bus_departure UNIQUE (bus_id, departure_date, departure_time),
  INDEX idx_trips_search (route_id, departure_date, status),
  INDEX idx_trips_driver (driver_id)
) ENGINE=InnoDB;

-- 11. Trip_seats
CREATE TABLE Trip_seats (
  trip_seat_id  INT AUTO_INCREMENT PRIMARY KEY,
  trip_id       INT NOT NULL,
  seat_id       INT NOT NULL,
  seat_status   VARCHAR(20) NOT NULL DEFAULT 'available',
  held_until    TIMESTAMP NULL DEFAULT NULL,
  price         DECIMAL(8,2) NOT NULL,
  updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT uq_trip_seat UNIQUE (trip_id, seat_id),
  CONSTRAINT fk_tseats_trip FOREIGN KEY (trip_id) REFERENCES Trips(trip_id),
  CONSTRAINT fk_tseats_seat FOREIGN KEY (seat_id) REFERENCES Seat_layout(seat_id),
  CONSTRAINT chk_tseats_status CHECK (seat_status IN ('available','held','booked','blocked')),
  CONSTRAINT chk_tseats_price CHECK (price >= 0),
  INDEX idx_tseats_status (trip_id, seat_status),
  INDEX idx_tseats_held (seat_status, held_until)
) ENGINE=InnoDB;

-- =====================================================================
-- STEP 5: USERS
-- =====================================================================

-- 12. Users
CREATE TABLE Users (
  user_id        INT AUTO_INCREMENT PRIMARY KEY,
  full_name      VARCHAR(150) NOT NULL,
  email          VARCHAR(150) NOT NULL,
  phone_number   VARCHAR(15)  NOT NULL,
  password_hash  VARCHAR(255) NOT NULL,
  gender         VARCHAR(10),
  date_of_birth  DATE,
  status         VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT uq_users_email UNIQUE (email),
  CONSTRAINT uq_users_phone UNIQUE (phone_number),
  CONSTRAINT chk_users_status CHECK (status IN ('active','blocked'))
) ENGINE=InnoDB;

-- 13. Passengers
CREATE TABLE Passengers (
  passenger_id     INT AUTO_INCREMENT PRIMARY KEY,
  user_id          INT NOT NULL,
  full_name        VARCHAR(150) NOT NULL,
  age              INT NOT NULL,
  gender           VARCHAR(10) NOT NULL,
  id_proof_type    VARCHAR(30),
  id_proof_number  VARCHAR(50),
  created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_passengers_user FOREIGN KEY (user_id) REFERENCES Users(user_id),
  CONSTRAINT chk_passengers_age CHECK (age > 0 AND age < 120),
  CONSTRAINT chk_passengers_gender CHECK (gender IN ('male','female','other')),
  INDEX idx_passengers_user (user_id)
) ENGINE=InnoDB;

-- =====================================================================
-- STEP 6: TRANSACTIONS
-- =====================================================================

-- 14. Bookings
CREATE TABLE Bookings (
  booking_id         INT AUTO_INCREMENT PRIMARY KEY,
  booking_reference  VARCHAR(20) NOT NULL,
  user_id            INT NOT NULL,
  trip_id            INT NOT NULL,
  boarding_stop_id   INT NOT NULL,
  dropping_stop_id   INT NOT NULL,
  total_seats        INT NOT NULL,
  total_fare         DECIMAL(10,2) NOT NULL,
  booking_status     VARCHAR(20) NOT NULL DEFAULT 'pending',
  booking_date       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT uq_bookings_ref UNIQUE (booking_reference),
  CONSTRAINT fk_bookings_user FOREIGN KEY (user_id) REFERENCES Users(user_id),
  CONSTRAINT fk_bookings_trip FOREIGN KEY (trip_id) REFERENCES Trips(trip_id),
  CONSTRAINT fk_bookings_board FOREIGN KEY (boarding_stop_id) REFERENCES Route_stops(route_stop_id),
  CONSTRAINT fk_bookings_drop FOREIGN KEY (dropping_stop_id) REFERENCES Route_stops(route_stop_id),
  CONSTRAINT chk_bookings_seats CHECK (total_seats > 0),
  CONSTRAINT chk_bookings_fare CHECK (total_fare >= 0),
  CONSTRAINT chk_bookings_status CHECK (booking_status IN ('pending','confirmed','cancelled','failed')),
  INDEX idx_bookings_user (user_id, booking_status),
  INDEX idx_bookings_trip (trip_id, booking_status)
) ENGINE=InnoDB;

-- 15. Booking_passengers
CREATE TABLE Booking_passengers (
  booking_passenger_id  INT AUTO_INCREMENT PRIMARY KEY,
  booking_id            INT NOT NULL,
  passenger_id          INT NOT NULL,
  trip_seat_id          INT NOT NULL,
  seat_number           VARCHAR(10) NOT NULL,
  fare                  DECIMAL(8,2) NOT NULL,
  created_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_bp_booking_seat UNIQUE (booking_id, trip_seat_id),
  CONSTRAINT fk_bp_booking FOREIGN KEY (booking_id) REFERENCES Bookings(booking_id),
  CONSTRAINT fk_bp_passenger FOREIGN KEY (passenger_id) REFERENCES Passengers(passenger_id),
  CONSTRAINT fk_bp_tripseat FOREIGN KEY (trip_seat_id) REFERENCES Trip_seats(trip_seat_id),
  CONSTRAINT chk_bp_fare CHECK (fare >= 0),
  INDEX idx_bp_passenger (passenger_id),
  INDEX idx_bp_tripseat (trip_seat_id)
) ENGINE=InnoDB;

-- 16. Payments
CREATE TABLE Payments (
  payment_id        INT AUTO_INCREMENT PRIMARY KEY,
  booking_id        INT NOT NULL,
  payment_method    VARCHAR(30) NOT NULL,
  transaction_id    VARCHAR(100) NOT NULL,
  amount            DECIMAL(10,2) NOT NULL,
  payment_status    VARCHAR(20) NOT NULL DEFAULT 'pending',
  payment_date      TIMESTAMP NULL DEFAULT NULL,
  gateway_response  TEXT,
  CONSTRAINT uq_payments_txn UNIQUE (transaction_id),
  CONSTRAINT fk_payments_booking FOREIGN KEY (booking_id) REFERENCES Bookings(booking_id),
  CONSTRAINT chk_payments_method CHECK (payment_method IN ('UPI','Card','NetBanking','Wallet')),
  CONSTRAINT chk_payments_amount CHECK (amount >= 0),
  CONSTRAINT chk_payments_status CHECK (payment_status IN ('pending','success','failed','refunded')),
  INDEX idx_payments_booking (booking_id)
) ENGINE=InnoDB;

-- 17. Cancellations
CREATE TABLE Cancellations (
  cancellation_id      INT AUTO_INCREMENT PRIMARY KEY,
  booking_id           INT NOT NULL,
  cancelled_by         VARCHAR(20) NOT NULL DEFAULT 'user',
  cancellation_reason  VARCHAR(255),
  cancellation_date    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  refund_percentage    DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  refund_amount        DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  refund_status        VARCHAR(20) NOT NULL DEFAULT 'pending',
  refund_date          TIMESTAMP NULL DEFAULT NULL,
  CONSTRAINT uq_cancel_booking UNIQUE (booking_id),
  CONSTRAINT fk_cancel_booking FOREIGN KEY (booking_id) REFERENCES Bookings(booking_id),
  CONSTRAINT chk_cancel_by CHECK (cancelled_by IN ('user','admin','system')),
  CONSTRAINT chk_cancel_pct CHECK (refund_percentage BETWEEN 0 AND 100),
  CONSTRAINT chk_cancel_amount CHECK (refund_amount >= 0),
  CONSTRAINT chk_cancel_rstatus CHECK (refund_status IN ('pending','processed','failed'))
) ENGINE=InnoDB;

-- 18. Refunds
CREATE TABLE Refunds (
  refund_id              INT AUTO_INCREMENT PRIMARY KEY,
  cancellation_id        INT NOT NULL,
  payment_id             INT NOT NULL,
  refund_amount          DECIMAL(10,2) NOT NULL,
  refund_method          VARCHAR(30) NOT NULL DEFAULT 'original_payment_method',
  refund_status          VARCHAR(20) NOT NULL DEFAULT 'initiated',
  refund_transaction_id  VARCHAR(100) NULL,
  initiated_at           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  completed_at           TIMESTAMP NULL DEFAULT NULL,
  CONSTRAINT uq_refunds_cancellation UNIQUE (cancellation_id),
  CONSTRAINT uq_refunds_txn UNIQUE (refund_transaction_id),
  CONSTRAINT fk_refunds_cancel FOREIGN KEY (cancellation_id) REFERENCES Cancellations(cancellation_id),
  CONSTRAINT fk_refunds_payment FOREIGN KEY (payment_id) REFERENCES Payments(payment_id),
  CONSTRAINT chk_refunds_amount CHECK (refund_amount >= 0),
  CONSTRAINT chk_refunds_method CHECK (refund_method IN ('original_payment_method','wallet_credit')),
  CONSTRAINT chk_refunds_status CHECK (refund_status IN ('initiated','processing','completed','failed')),
  INDEX idx_refunds_payment (payment_id)
) ENGINE=InnoDB;

-- =====================================================================
-- STEP 7: GROWTH & OPERATIONS
-- =====================================================================

-- 19. Coupons
CREATE TABLE Coupons (
  coupon_id             INT AUTO_INCREMENT PRIMARY KEY,
  coupon_code           VARCHAR(30) NOT NULL,
  description           VARCHAR(255),
  discount_type         VARCHAR(20) NOT NULL,
  discount_value        DECIMAL(8,2) NOT NULL,
  max_discount_amount   DECIMAL(8,2),
  min_booking_amount    DECIMAL(8,2) NOT NULL DEFAULT 0.00,
  valid_from            DATE NOT NULL,
  valid_until           DATE NOT NULL,
  usage_limit_per_user  INT NOT NULL DEFAULT 1,
  total_usage_limit     INT,
  status                VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_coupons_code UNIQUE (coupon_code),
  CONSTRAINT chk_coupons_type CHECK (discount_type IN ('percentage','flat')),
  CONSTRAINT chk_coupons_value CHECK (discount_value > 0),
  CONSTRAINT chk_coupons_dates CHECK (valid_until >= valid_from),
  CONSTRAINT chk_coupons_status CHECK (status IN ('active','inactive','expired'))
) ENGINE=InnoDB;

-- 20. Booking_coupons
CREATE TABLE Booking_coupons (
  booking_coupon_id  INT AUTO_INCREMENT PRIMARY KEY,
  booking_id         INT NOT NULL,
  coupon_id          INT NOT NULL,
  discount_applied   DECIMAL(8,2) NOT NULL,
  applied_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_bc_booking_coupon UNIQUE (booking_id, coupon_id),
  CONSTRAINT fk_bc_booking FOREIGN KEY (booking_id) REFERENCES Bookings(booking_id),
  CONSTRAINT fk_bc_coupon FOREIGN KEY (coupon_id) REFERENCES Coupons(coupon_id),
  CONSTRAINT chk_bc_discount CHECK (discount_applied >= 0),
  INDEX idx_bc_coupon (coupon_id)
) ENGINE=InnoDB;

-- 21. Notifications
CREATE TABLE Notifications (
  notification_id    INT AUTO_INCREMENT PRIMARY KEY,
  user_id            INT NOT NULL,
  booking_id         INT NULL,
  notification_type  VARCHAR(30) NOT NULL,
  title              VARCHAR(150),
  message            TEXT NOT NULL,
  status             VARCHAR(20) NOT NULL DEFAULT 'pending',
  sent_at            TIMESTAMP NULL DEFAULT NULL,
  CONSTRAINT fk_notif_user FOREIGN KEY (user_id) REFERENCES Users(user_id),
  CONSTRAINT fk_notif_booking FOREIGN KEY (booking_id) REFERENCES Bookings(booking_id),
  CONSTRAINT chk_notif_type CHECK (notification_type IN ('sms','email','push')),
  CONSTRAINT chk_notif_status CHECK (status IN ('sent','failed','pending')),
  INDEX idx_notif_user (user_id),
  INDEX idx_notif_booking (booking_id)
) ENGINE=InnoDB;

-- 22. Reviews_ratings
CREATE TABLE Reviews_ratings (
  review_id    INT AUTO_INCREMENT PRIMARY KEY,
  booking_id   INT NOT NULL,
  user_id      INT NOT NULL,
  trip_id      INT NOT NULL,
  rating       INT NOT NULL,
  review_text  VARCHAR(500),
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_review_booking_user UNIQUE (booking_id, user_id),
  CONSTRAINT fk_review_booking FOREIGN KEY (booking_id) REFERENCES Bookings(booking_id),
  CONSTRAINT fk_review_user FOREIGN KEY (user_id) REFERENCES Users(user_id),
  CONSTRAINT fk_review_trip FOREIGN KEY (trip_id) REFERENCES Trips(trip_id),
  CONSTRAINT chk_review_rating CHECK (rating BETWEEN 1 AND 5),
  INDEX idx_review_trip (trip_id)
) ENGINE=InnoDB;

-- 23. Admin_users
CREATE TABLE Admin_users (
  admin_id       INT AUTO_INCREMENT PRIMARY KEY,
  full_name      VARCHAR(150) NOT NULL,
  email          VARCHAR(150) NOT NULL,
  password_hash  VARCHAR(255) NOT NULL,
  role           VARCHAR(30) NOT NULL DEFAULT 'support_staff',
  status         VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_admin_email UNIQUE (email),
  CONSTRAINT chk_admin_role CHECK (role IN ('super_admin','ops_manager','support_staff')),
  CONSTRAINT chk_admin_status CHECK (status IN ('active','inactive'))
) ENGINE=InnoDB;

-- 24. Operators (optional - only for multi-operator expansion)
CREATE TABLE Operators (
  operator_id    INT AUTO_INCREMENT PRIMARY KEY,
  operator_name  VARCHAR(150) NOT NULL,
  contact_email  VARCHAR(150),
  contact_phone  VARCHAR(15),
  license_number VARCHAR(50),
  rating         DECIMAL(2,1),
  status         VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT chk_operators_rating CHECK (rating IS NULL OR rating BETWEEN 0 AND 5),
  CONSTRAINT chk_operators_status CHECK (status IN ('active','inactive'))
) ENGINE=InnoDB;

-- =====================================================================
-- OPTIONAL: reference seed data
-- =====================================================================

-- =====================================================================
-- OPTIONAL: seat-hold cleanup (frees expired holds every minute).
-- Requires: SET GLOBAL event_scheduler = ON;
-- =====================================================================
DELIMITER $$
CREATE EVENT IF NOT EXISTS ev_release_expired_seat_holds
ON SCHEDULE EVERY 1 MINUTE
DO
BEGIN
  UPDATE Trip_seats
     SET seat_status = 'available', held_until = NULL
   WHERE seat_status = 'held'
     AND held_until IS NOT NULL
     AND held_until < NOW();
END$$
DELIMITER ;

-- =====================================================================
-- END OF SCRIPT
-- =====================================================================

-- =====================================================================
-- Bus Booking DB - realistic seed data (Oct 1 2025 -> Dec 31 2025)
-- Run AFTER bus_booking_mysql_schema.sql   |  MySQL 8.0+
-- Data is synthetic-but-realistic: real Indian cities/bus terminals, real road
-- distances, festival & weekend demand patterns, coupon rules, refund policy.
-- =====================================================================
USE bus_booking_db;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
SET UNIQUE_CHECKS=0;
SET AUTOCOMMIT=0;













-- Trip_seats: one row per (trip, seat), generated from Trips x Seat_layout
SELECT ROW_NUMBER() OVER (ORDER BY t.trip_id, s.seat_id), t.trip_id, s.seat_id, 'available', ROUND(t.fare * s.price_multiplier, 2), t.created_at
FROM Trips t JOIN Seat_layout s ON s.bus_id = t.bus_id
ORDER BY t.trip_id, s.seat_id;





-- Mark seats of confirmed bookings as booked; block seats of cancelled trips
UPDATE Trip_seats ts JOIN Booking_passengers bp ON bp.trip_seat_id = ts.trip_seat_id
JOIN Bookings b ON b.booking_id = bp.booking_id AND b.booking_status = 'confirmed'
SET ts.seat_status = 'booked', ts.updated_at = b.booking_date;
UPDATE Trip_seats ts JOIN Trips t ON t.trip_id = ts.trip_id SET ts.seat_status = 'blocked' WHERE t.status = 'cancelled';








COMMIT;
SET FOREIGN_KEY_CHECKS=1;
SET UNIQUE_CHECKS=1;
SET AUTOCOMMIT=1;

-- Quick verification
SELECT 'Users' AS tbl, COUNT(*) AS n FROM Users UNION ALL SELECT 'Trips', COUNT(*) FROM Trips UNION ALL SELECT 'Trip_seats', COUNT(*) FROM Trip_seats
UNION ALL SELECT 'Bookings', COUNT(*) FROM Bookings UNION ALL SELECT 'Booking_passengers', COUNT(*) FROM Booking_passengers UNION ALL SELECT 'Payments', COUNT(*) FROM Payments
UNION ALL SELECT 'Cancellations', COUNT(*) FROM Cancellations UNION ALL SELECT 'Refunds', COUNT(*) FROM Refunds UNION ALL SELECT 'Reviews_ratings', COUNT(*) FROM Reviews_ratings;


show tables;